// WF_SETUP · plan
// Aceeași funcție folosită de scripts/provision-ghl.mjs — un singur loc de întreținut.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

/**
 * Derivările din config: tag-uri, custom fields cu opțiuni, custom values.
 *
 * Funcții pure, fără I/O, ca aceeași logică să ruleze și în scripturi (Node) și
 * într-un node Code din n8n. Sursa unică: dacă scriptul și workflow-ul ar calcula
 * separat lista de tag-uri, ar diverge exact când doare — la al doilea client.
 */

/** Toate tag-urile derivate din axele de taxonomie. */
function deriveAxisTags(config) {
  const out = [];
  for (const [axisName, axis] of Object.entries(config.taxonomy.axes)) {
    for (const value of axis.values) {
      out.push({ tag: `${axis.tag_prefix}${value.key}`, axis: axisName, key: value.key, label: value.label });
    }
  }
  return out;
}

/** Tag-urile de sistem: consimțământ, opt-out, stare de flux, ciclu de viață. */
function deriveSystemTags(config) {
  const p = config.taxonomy.system_tag_prefixes;
  const out = [];
  for (const channel of Object.keys(config.compliance.consent_fields)) {
    out.push({ tag: `${p.consent}${channel}`, axis: '_consent', key: channel, label: `Consimțământ ${channel}` });
  }
  for (const [channel, tag] of Object.entries(config.compliance.optout_tags)) {
    out.push({ tag, axis: '_optout', key: channel, label: `Opt-out ${channel}` });
  }
  for (const flowId of Object.keys(config.flows)) {
    out.push({ tag: `${p.flow_state}${flowId}`, axis: '_flow_state', key: flowId, label: `În fluxul ${flowId}` });
  }
  for (const lifecycle of ['import', 'lead', 'client', 'client_fidel', 'inactiv']) {
    out.push({ tag: `${p.lifecycle}${lifecycle}`, axis: '_lifecycle', key: lifecycle, label: `Ciclu de viață: ${lifecycle}` });
  }
  return out;
}

function deriveAllTags(config) {
  return [...deriveAxisTags(config), ...deriveSystemTags(config)];
}

/**
 * Custom fields cu opțiunile completate din axa asociată.
 * Opțiunile nu se scriu de două ori în config: axa e sursa unică.
 */
function deriveCustomFields(config) {
  return config.custom_fields.map((field) => {
    if (!field.axis) return { ...field, options: field.options || [] };
    const axis = config.taxonomy.axes[field.axis];
    if (!axis) throw new Error(`custom_field "${field.key}" trimite la axa inexistentă "${field.axis}"`);
    return { ...field, options: axis.values.map((v) => v.label) };
  });
}

function resolvePath(obj, dotted) {
  return dotted.split('.').reduce((acc, key) => (acc == null ? undefined : acc[key]), obj);
}

/** Custom values GHL, cu valorile rezolvate din config. */
function deriveCustomValues(config) {
  return (config.custom_values || []).map(({ key, from }) => {
    const value = resolvePath(config, from);
    return { key, from, value: value === undefined ? null : String(value) };
  });
}

/**
 * Celulele de conținut de generat: flux × variantă de text × canal.
 *
 * Distincția care ține volumul sub control: `segmented_by` spune CINE primește
 * (filtru de audiență), `content_varies_by` spune pe ce axe se scrie text DIFERIT.
 * Fără separarea asta, cele 5 axe cerute pentru ofertele personalizate produc
 * peste 10.000 de texte de revizuit uman.
 */
function deriveContentCells(config) {
  const cells = [];
  for (const [flowId, flow] of Object.entries(config.flows)) {
    if (!flow.enabled) continue;
    const varyBy = flow.content_varies_by || [];
    const axes = varyBy.map((name) => {
      const axis = config.taxonomy.axes[name];
      if (!axis) throw new Error(`flow "${flowId}".content_varies_by trimite la axa inexistentă "${name}"`);
      return { name, values: axis.values };
    });

    let combos = [{}];
    for (const axis of axes) {
      combos = combos.flatMap((combo) => axis.values.map((v) => ({ ...combo, [axis.name]: v.key })));
    }

    for (const step of flow.steps) {
      if (step.channel === 'task') continue;
      for (const segment of combos) {
        cells.push({
          flow_id: flowId, step_id: step.id, channel: step.channel,
          category: step.category, template: step.template, segment,
        });
      }
    }
  }
  return cells;
}

/**
 * Planul de provisioning GHL: ce trebuie creat, ce actualizat, ce e deja la zi.
 *
 * Funcție pură, folosită de DOUĂ rulări diferite ale aceleiași logici:
 *  - scripts/provision-ghl.mjs, când ai acces direct la API-ul GHL;
 *  - workflow-ul „WF_SETUP · Provisioning GHL", când n8n e cel care ajunge la GHL
 *    (ex. rețeaua de unde rulezi scriptul nu are voie la leadconnectorhq.com).
 *
 * Aceeași funcție în ambele = același rezultat. Idempotentă prin construcție:
 * compară ce cere configul cu ce există deja și emite doar diferența.
 */



const norm = (s) => String(s ?? '').trim().toLowerCase();

/**
 * @param {object} args
 * @param {object} args.config
 * @param {object} args.existing
 * @param {Array} args.existing.customFields  ce a returnat GET /locations/{id}/customFields
 * @param {Array} args.existing.tags
 * @param {Array} args.existing.customValues
 * @returns {{operations: Array, summary: object, conflicts: Array}}
 */
function buildProvisionPlan({ config, existing }) {
  const operations = [];
  const conflicts = [];
  const skipped = [];
  const locationPath = '/locations/{locationId}';

  // ── Custom fields ──
  const wantedFields = deriveCustomFields(config);
  const fieldsByName = new Map((existing.customFields || []).map((f) => [norm(f.name), f]));

  for (const field of wantedFields) {
    const current = fieldsByName.get(norm(field.name));
    const body = {
      name: field.name,
      dataType: field.dataType,
      ...(field.options?.length ? { options: field.options } : {}),
    };

    if (!current) {
      operations.push({
        kind: 'custom_field', action: 'create', label: field.name,
        detail: `${field.dataType}${field.options?.length ? ` · ${field.options.length} opțiuni` : ''}`,
        method: 'POST', path: `${locationPath}/customFields`, body: { ...body, model: 'contact' },
      });
      continue;
    }

    // Tipul unui câmp deja populat nu se schimbă automat: ar pierde date.
    if (norm(current.dataType) !== norm(field.dataType)) {
      conflicts.push({
        kind: 'custom_field', label: field.name,
        detail: `în GHL e ${current.dataType}, configul cere ${field.dataType} — rezolvă manual`,
      });
      continue;
    }

    const currentOptions = (current.picklistOptions || current.options || [])
      .map((o) => norm(typeof o === 'string' ? o : (o?.value ?? o?.name ?? o?.label)))
      .sort();
    const wantedOptions = (field.options || []).map(norm).sort();

    if (wantedOptions.length && JSON.stringify(currentOptions) !== JSON.stringify(wantedOptions)) {
      operations.push({
        kind: 'custom_field', action: 'update', label: field.name,
        detail: `opțiuni: ${currentOptions.length} → ${wantedOptions.length}`,
        method: 'PUT', path: `${locationPath}/customFields/${current.id}`, body,
      });
    } else {
      skipped.push({ kind: 'custom_field', label: field.name });
    }
  }

  // ── Tag-uri ──
  const wantedTags = deriveAllTags(config);
  const haveTags = new Set((existing.tags || []).map((t) => norm(t.name)));

  for (const tag of wantedTags) {
    if (haveTags.has(norm(tag.tag))) {
      skipped.push({ kind: 'tag', label: tag.tag });
      continue;
    }
    operations.push({
      kind: 'tag', action: 'create', label: tag.tag, detail: tag.label,
      method: 'POST', path: `${locationPath}/tags`, body: { name: tag.tag },
    });
  }

  // ── Custom values ──
  const wantedValues = deriveCustomValues(config);
  const valuesByName = new Map((existing.customValues || []).map((v) => [norm(v.name), v]));

  for (const cv of wantedValues) {
    const current = valuesByName.get(norm(cv.key));
    if (!current) {
      operations.push({
        kind: 'custom_value', action: 'create', label: cv.key, detail: cv.value,
        method: 'POST', path: `${locationPath}/customValues`, body: { name: cv.key, value: cv.value },
      });
    } else if (String(current.value) !== String(cv.value)) {
      operations.push({
        kind: 'custom_value', action: 'update', label: cv.key,
        detail: `"${current.value}" → "${cv.value}"`,
        method: 'PUT', path: `${locationPath}/customValues/${current.id}`,
        body: { name: cv.key, value: cv.value },
      });
    } else {
      skipped.push({ kind: 'custom_value', label: cv.key });
    }
  }

  const count = (kind, action) => operations.filter((o) => o.kind === kind && o.action === action).length;
  return {
    operations,
    conflicts,
    skipped,
    summary: {
      to_create: operations.filter((o) => o.action === 'create').length,
      to_update: operations.filter((o) => o.action === 'update').length,
      unchanged: skipped.length,
      conflicts: conflicts.length,
      custom_fields: { create: count('custom_field', 'create'), update: count('custom_field', 'update') },
      tags: { create: count('tag', 'create') },
      custom_values: { create: count('custom_value', 'create'), update: count('custom_value', 'update') },
    },
  };
}

// ── glue n8n ──
const params = $('Citește parametrii').first().json;
const config = $('Încarcă configul').first().json.config;

const existing = {
  customFields: $('Citește custom fields').first().json?.data?.customFields || [],
  tags: $('Citește tag-urile').first().json?.data?.tags || [],
  customValues: $('Citește custom values').first().json?.data?.customValues || [],
};

const plan = buildProvisionPlan({ config, existing });

return [{ json: {
  client_id: params.client_id,
  apply: params.apply,
  summary: plan.summary,
  conflicts: plan.conflicts,
  operations: plan.operations,
} }];

// WF_SETUP · execuție
// Un item per operațiune; SW01 le execută secvențial, ca un 429 să nu lase sub-contul pe jumătate provisionat.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

const plan = $input.first().json;
if (!plan.operations.length) return [{ json: { client_id: plan.client_id, nothing_to_do: true } }];

return plan.operations.map((operation) => ({ json: {
  client_id: plan.client_id,
  method: operation.method,
  path: operation.path,
  body: operation.body,
  _op: { kind: operation.kind, action: operation.action, label: operation.label },
} }));

// WF_SETUP · raport
// Ce s-a făcut, ce a rămas de rezolvat manual.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

const plan = $('Construiește planul').first().json;
const applied = plan.apply ? $input.all().length : 0;

const lines = [
  plan.apply ? `Aplicat pe "${plan.client_id}": ${applied} operațiuni.` : `Plan pentru "${plan.client_id}" (nu s-a scris nimic).`,
  `  de creat:      ${plan.summary.to_create}`,
  `  de actualizat: ${plan.summary.to_update}`,
  `  neschimbate:   ${plan.summary.unchanged}`,
  `  custom fields: +${plan.summary.custom_fields.create} ~${plan.summary.custom_fields.update}`,
  `  tag-uri:       +${plan.summary.tags.create}`,
  `  custom values: +${plan.summary.custom_values.create} ~${plan.summary.custom_values.update}`,
];
if (plan.conflicts.length) {
  lines.push('', `${plan.conflicts.length} conflicte de rezolvat manual în GHL:`);
  for (const c of plan.conflicts) lines.push(`  ${c.label} — ${c.detail}`);
}

return [{ json: { client_id: plan.client_id, applied_operations: applied, summary: plan.summary, conflicts: plan.conflicts, report: lines.join('\n') } }];
